"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[551],{2911(e){e.exports=JSON.parse('{"title":"React 19 \ucd9c\uc2dc\ub294 \ub354 \ub2a6\uc5b4\uc9c8 \uac83\uc774\ub2e4","date":"2024-07-03","coverUrl":null,"html":"<p data-notion-block-id=\\"0ce572a5-53a3-4968-9539-d4f6251756fd\\">2\uc8fc\uce58\ub97c \ub9cc\ub4e4\ub824\uace0 \uae30\uc0ac\ub97c \ubaa8\ub450 \ubd24\ub354\ub2c8 2\uc8fc\ub3d9\uc548 \ub108\ubb34 \ub9ce\uc740 \uc18c\uc2dd\uc774 \uc3df\uc544\uc84c\ub124\uc694.. \ucd5c\ub300\ud55c \ub2f4\uc558\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"005b807a-30f0-4e76-878f-dc1dfb1489ef\\" id=\\"005b807a-30f0-4e76-878f-dc1dfb1489ef\\">React 19 \ucd9c\uc2dc\ub294 \ub354 \ub2a6\uc5b4\uc9c8 \uac83\uc774\ub2e4</h2><a href=\\"https://tkdodo.eu/blog/react-19-and-suspense-a-drama-in-3-acts\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/react-19-and-suspense-a-drama-in-3-acts</a><a href=\\"https://blog.codeminer42.com/how-react-19-almost-made-the-internet-slower/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.codeminer42.com/how-react-19-almost-made-the-internet-slower/</a><p data-notion-block-id=\\"81ae4741-35b8-4979-b548-be656c5d20af\\"><a href=\\"https://velog.io/@cnsrn1874/react-19-and-suspense-a-drama-in-3-acts\\">(\uccab\ubc88\uc9f8 \uae00\uc758 \ud55c\uad6d\uc5b4 \ubc88\uc5ed)</a></p><p data-notion-block-id=\\"ab0bbccb-44e9-46cd-ab86-bac1a0793c39\\"><b>\uc2ec\uc724\uc12d</b>: React 19\uc5d0\uc11c \ud074\ub77c\uc774\uc5b8\ud2b8 \uce21 Suspense\uac00 waterfall\ud615\uc2dd\uc73c\ub85c \uc9c4\ud589\ub41c\ub2e4\ub294 \uac83\uc5d0 \ub300\ud55c \ud1a0\ub860\uc774 \uc788\uc5c8\uace0, \uc774 \ub3d9\uc791\uc774 \uc801\uc808\ud558\uc9c0 \uc54a\uace0, \ub354 \ub9ce\uc740 \ud53c\ub4dc\ubc31\uacfc \uc218\uc815\uc744 \uac70\uce58\uace0 React 19\ub97c \ucd9c\uc2dc\ud560 \uac83\uc774\ub77c\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. \uc774\uc804\uc5d0 <a href=\\"https://ones-to-watch.ethansup.net/news/post/a5902c7d-ee33-4db6-aaea-ea4820a7562f#bd09632a-7805-48c6-a538-fde6442ffd02\\">React-Query\uc640 RSC\ub97c \uac19\uc774 \uc4f0\uae30</a>(React 18)\uc5d0\uc11c\ub3c4 \ub098\uc628 Server actions\ub3c4 waterfall\ud615\uc2dd\uc73c\ub85c \uc9c4\ud589\ub418\uc11c \ub9ce\uc740 \uc0dd\uac01\uc774 \ub4e4\uae30\ub3c4 \ud588\uc5c8\ub358 \uac83\uc774 \uc0dd\uac01\ub098\ub124\uc694. \uc774\uc804\uc5d0\ub3c4 \ub098\uc628 <a href=\\"https://ones-to-watch.ethansup.net/news/post/ffe0e0a6901b4f3e8b9a0e48601ad787#6e1950cf-ceb7-418a-a85a-e4b7aef10d94\\">React 18\uc5d0\uc11c\uc758 \ubd88\ub9cc</a>\uacfc \uac19\uc774, \uc548\uc815\ub41c \uc0c1\ud0dc\ub85c \ucd9c\uc2dc\ud55c\ub2e4\uba74 \uc88b\uc740 \uae30\ub2a5\ub4e4\uc774\ub77c\uace0 \uc0dd\uac01\ud574\uc11c \uc81c\ub300\ub85c \ub9cc\ub4e4\uc5c8\uc73c\uba74 \uc88b\uaca0\ub124\uc694.</p><p data-notion-block-id=\\"bd2e14fa-7109-45aa-aa09-c4e5419a4d65\\"><b>\uae40\ub300\uad00</b>: React 19\uc5d0 \ub300\ud55c \uc18c\uc2dd\uc740 \uc704\uc758 \ubca8\ub85c\uadf8 \ubc88\uc5ed \uae00\uc744 \ud1b5\ud574 \ucc98\uc74c \uc54c\uac8c \ub418\uc5c8\ub294\ub370, React 19\ub85c \uc624\uba74\uc11c waterFall \ubc29\uc2dd\uc73c\ub85c \uc9c4\ud589\ud55c\ub2e4\ub294 \uc18c\uc2dd\uc740 \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc790\ub4e4 \uc0ac\uc774\uc5d0\uc11c \ub9e4\uc6b0 \ub728\uac70\uc6b4 \uac10\uc790\uc600\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc774\uc288\ub97c \ud1b5\ud574 \ub9ce\uc740 \uac1c\ubc1c\uc790\ub4e4\uc758 \ud53c\ub4dc\ubc31\uc774 \uc774\uc5b4\uc9c0\uba74\uc11c React 19\uc5d0 \uad00\uc2ec\uc774 \uc9d1\uc911\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \ubb3c\ub860 React\ud300\uc774 \uc774\ubc88 \uc0ac\uac74\uc73c\ub85c \ub9ce\uc740 \ud53c\ub4dc\ubc31\uc744 \ubc1b\uc544 \uc798 \uc218\uc815\ud558\uaca0\uc9c0\ub9cc, \uc2e4\uc81c\ub85c \uc5b4\ub5bb\uac8c \ud074\ub77c\uc774\uc5b8\ud2b8\uc5d0\uc11c\uc758 Suspense \ub85c\uc9c1\uc774 \ud758\ub7ec\uac08\uc9c0\ub294 \ubaa8\ub985\ub2c8\ub2e4(\uc608\uc2dc\ub85c <a href=\\"https://github.com/facebook/react/issues/29898\\">\uc54c\uace0\ub9ac\uc998 \uc81c\uc548</a>\ub3c4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4). \uadf8\ub798\uc11c \uc774\ub7ec\ud55c \uc774\uc288\uc640 \uae30\uc220\uc758 \ubcc0\ud654\ub97c \uc798 \uc8fc\uc2dc\ud574\uc57c \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"94aa8484-fa6b-4f26-aa0b-4a1d93e7b5cd\\" id=\\"94aa8484-fa6b-4f26-aa0b-4a1d93e7b5cd\\">React\uc640 SOLID \uc6d0\uce59</h2><a href=\\"https://www.perssondennis.com/articles/write-solid-react-hooks\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.perssondennis.com/articles/write-solid-react-hooks</a><p data-notion-block-id=\\"becc915e-a2e3-45b5-a6ba-857894226f9f\\"><b>\uc2ec\uc724\uc12d</b>: \uae38\uc5b4\uc11c \uc5ec\ub7ec \ubb38\ub2e8\uc73c\ub85c \ub098\ub204\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4. :)</p><p data-notion-block-id=\\"81005ad6-30b1-48d5-8437-33e82a93cedc\\">\uc774\uc804\uc5d0 \uce74\uce74\uc624 \uc5d4\ud130\ud14c\uc774\uba3c\ud2b8 \uae30\uc220 \ube14\ub85c\uadf8\uc758 <a href=\\"https://fe-developers.kakaoent.com/2023/230330-frontend-solid/\\">\ud504\ub860\ud2b8\uc5d4\ub4dc\uc640 SOLID \uc6d0\uce59</a>\uacfc \ube44\uc2b7\ud558\uc9c0\ub9cc, React\uc5d0 \uad6d\ud55c\ud574\uc11c SOLID \uc6d0\uce59\uc744 \uc5b4\ub290 \uacf3\uc5d0\uc11c \uc0ac\uc6a9\ud574\ubcfc \uc218 \uc788\ub294\uc9c0 \uc0dd\uac01\ud574\ubcfc \uc218 \uc788\ub294 \uae00\uc785\ub2c8\ub2e4. \uce74\uce74\uc624 \uc5d4\ud130\ud14c\uc774\uba3c\ud2b8 \uae30\uc220 \ube14\ub85c\uadf8\uc758 \uae00\uc740 UI \ucd9c\ub825\uacfc \ucef4\ud3ec\ub10c\ud2b8 \uad00\uc810\uc73c\ub85c \uc0b4\ud3b4\ubd24\ub2e4\uba74, \uc774 \uae00\uc740 Custom Hook\uacfc React\uc758 \uae30\ubcf8 hooks\uc5d0 \uc9d1\uc911\ud574\uc11c \uc6d0\uce59\uc774 \uc5b4\ub5bb\uac8c \uc801\uc6a9\ub420\uae4c \uc0b4\ud3b4\ubcf4\ub294 \uacfc\uc815\uc744 \uac70\uce69\ub2c8\ub2e4. \uadf8\ub3d9\uc548 \ud504\ub860\ud2b8\uc5d4\ub4dc\uac00 \uac70\uccd0\uc624\uba74\uc11c \uae30\uc874\uc758 \ud328\ud134\uc758 \uc801\uc6a9 \ubc29\ubc95\uc5d0 \ub300\ud574 \uace0\ubbfc\ud574\ubcf4\uace0, \uc2e0\uaddc \ud328\ud134\uc5d0 \ub300\ud574 \uc5b4\ub5bb\uac8c \ub2e4\ub904\uc57c \ud560\uc9c0\uc5d0 \ub300\ud55c \uace0\ubbfc\ub4e4\uc774 \ub9ce\uc774 \uac70\uce58\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uc774\uc5d0 \ub300\ud574\uc11c\ub294 \ub9ce\uc740 \uc8fc\uc7a5\uacfc, \ub9ce\uc740 \ube44\ud310\ub4e4\uc774 \ub530\ub974\uae30 \ub9c8\ub828\uc785\ub2c8\ub2e4. </p><p data-notion-block-id=\\"1d9bb66c-9479-47d8-840d-1c3dc9816caa\\">\uac1d\uccb4\uc9c0\ud5a5\uc758 \ub300\ud45c\uc778 \uc774 SOLID \uc6d0\uce59 \ub610\ud55c \uadf8\ub807\uc8e0. \uc6d0\uce59\uc744 \ub530\ub974\uac8c \ub418\uba74 \uc2dc\uac04\uc774 \ub9e4\uc6b0 \uc624\ub798\uac78\ub9b4 \ubfd0\ub354\ub7ec, \uc6d0\uce59\uc758 \uc81c\ud55c\ub54c\ubb38\uc5d0 \uac04\ub2e8\ud558\uac8c \uc9dc\uc77c \ucf54\ub4dc\uac00 \uc5b4\ub835\uac8c \ub3cc\uc544\uac00\ub294 \uacbd\uc6b0\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc6d0\uce59\uc774 \uc544\uc608 \uc5c6\ub2e4\uba74, \ucf54\ub4dc\uac00 \uc911\uad6c\ub09c\ubc29\uc774 \ub418\uc5b4\uc11c \ubaa8\ub450\uac00 \uc774 \ucf54\ub4dc\ub294 \ub808\uac70\uc2dc\uc57c \ud558\uace0 \uac74\ub4e4 \uc0dd\uac01\uc870\ucc28 \ubabb\ud558\uac8c \ub418\uaca0\uc8e0. \uac1c\uc778\uc801\uc73c\ub85c\ub294 \uc6d0\uce59\uc774 \uc788\ub294 \uc774\uc720\ub294 \uc6b0\ub9ac\uac00 \uc18c\ud1b5\ud558\ub294 \uc5b8\uc5b4\ub97c \ub3d9\uc77c\ud558\uac8c \uac00\uc838\uac00\uae30 \uc704\ud574\uc11c\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc6d0\uce59\uc5d0\uc11c \ub9d0\ud558\ub294 \uc6a9\uc5b4\ub97c \ubc14\ud0d5\uc73c\ub85c \uc6b0\ub9ac\uac00 \ucf54\ub4dc\ub97c \uc9dc\ub294 \ubc29\uc2dd\uc744 \uc5b4\ub5bb\uac8c \uacb0\uc815\ud558\ub290\ub0d0\uc5d0 \ub530\ub77c \uac08\ub9ac\ub294 \uac83\uc774\uc8e0. </p><p data-notion-block-id=\\"b5ca20c9-9ccc-45eb-9307-4787b8dbc291\\">\ub098\uc911\uc5d0 \ub530\ub85c \uc4f0\ub824\uace0 \ud588\ub358 <a href=\\"https://toss.tech/article/firesidechat_frontend_2\\">\ud1a0\uc2a4 \ubaa8\ub2e5\ubd88\uc758 OOP FP \ub17c\uc7c1</a>\uc5d0\uc11c\ub3c4 \ubcf4\uc600\ub4ef\uc774, FP\uc640 OOP\uac00 \ubc18\ub300\ub418\ub294 \uac1c\ub150\uc774 \uc544\ub2c8\ub77c, \uacf5\uc874\ud560 \uc218 \uc788\ub294 \uac1c\ub150\uc774\ub77c\uace0 \ud588\ub358 \uac83\uacfc \ube44\uc2b7\ud55c \uad00\uc810\uc73c\ub85c \ubc14\ub77c\ubd24\uc73c\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4. FP\uc640 OOP\uac00 \ub2e4\ub978 \ub9d0\ub85c \uac19\uc740 \uac1c\ub150\uc744 \ub9d0\ud558\uace0 \uc788\ub294 \uac83\ub3c4 \uc788\ub4ef\uc774, \ub450 \uac1c\ub150\uc740 \ubc29\ud5a5\uc740 \ube44\uc2b7\ud558\uc9c0\ub9cc \ub2e4\ub974\uac8c \ud574\uc11d\ub418\uc5b4\uc11c \uc6d0\uce59\uc774 \ub41c \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uadf8\ub7f0 \uc758\ubbf8\uc5d0\uc11c \ud55c \uc6d0\uce59\uc744 \ubaa8\ub450 \ud56d\uc0c1 \ub530\ub97c \ud544\uc694\ub294 \uc5c6\uace0, \uad00\uc810\uc744 \ub298\ub9ac\uae30 \uc704\ud574\uc11c \uc774\ub7f0 \ud574\uc11d(\uc6d0\uce59)\uc758 \ud574\uc11d\uc774 \uc788\ub2e4\ub77c\ub294 \uc2dd\uc73c\ub85c \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4. </p><p data-notion-block-id=\\"04b9c8eb-2edb-4718-a7e2-9111e0ac7b06\\">\uae00 \ub0b4\uc6a9\uc740 \ud568\uc218\uac00 \uc5ec\ub7ec \ub3d9\uc791 \ud558\uac8c \ud558\uc9c0 \ub9c8\ub77c / \ucd94\uc0c1\ud654\ub97c \uacac\uace0\ud558\uac8c \ub9cc\ub4e4\uc5b4\ub77c\uc5d0\uc11c \ubc97\uc5b4\ub098\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uadf8\ub798\ub3c4 \uc774\ub7f0 \uad00\uc810\ub3c4 \uc788\ub2e4\ub294 \uc0dd\uac01\uc744 \ub098\uc911\uc5d0\ub3c4 \ub5a0\uc62c\ub9ac\uae30 \uc704\ud574 \ubcf4\uc168\uc73c\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4. \uac1c\uc778\uc801\uc73c\ub85c \ubaa8\ub450 \ucd94\uc0c1\ud654 \uacfc\uc815\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc774\ub77c \ucd94\uc0c1\ud654\uc5d0 \ub300\ud55c \uc811\uadfc \ubc29\uc2dd\uc744 \ud300\uc5d0\uc11c \uc815\ud558\uba74 \uc88b\uaca0\ub2e4\ub294 \uc0dd\uac01\ub3c4 \ub4dc\ub124\uc694. \ud83d\ude05</p><h2 data-notion-block-id=\\"411a2a32-43b4-46ac-8933-e00dd3b7cb2c\\" id=\\"411a2a32-43b4-46ac-8933-e00dd3b7cb2c\\">Slack\uc758 AI\uae30\ubc18 \ub77c\uc774\ube0c\ub7ec\ub9ac \uad50\uccb4</h2><a href=\\"https://slack.engineering/balancing-old-tricks-with-new-feats-ai-powered-conversion-from-enzyme-to-react-testing-library-at-slack/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://slack.engineering/balancing-old-tricks-with-new-feats-ai-powered-conversion-from-enzyme-to-react-testing-library-at-slack/</a><p data-notion-block-id=\\"2c6116f4-5219-45a5-93da-e35ddbce6b95\\"><b>\uc2ec\uc724\uc12d</b>: RTL\uc740 \ube14\ub799\ubc15\uc2a4 \ud14c\uc2a4\ud305 \uc811\uadfc \ubc29\uc2dd\uc744 \uc798 \uc801\uc6a9\ud558\uae30 \uc27d\uac8c, \uadf8\ub9ac\uace0 \ud14c\uc2a4\ud2b8\ub97c \uc791\uc131\ud558\uae30 \uc27d\uac8c \ub9cc\ub4e4\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub9ac\uace0 React 16\uc774 \ub098\uc624\uac8c \ub41c \uc774\ud6c4 Enzyme\uc758 \uc9c0\uc6d0\uc774 \uc810\uc810 \ub0ae\uc544\uc84c\uc2b5\ub2c8\ub2e4. Slack\uc5d0\uc11c\ub294 \ubaa8\ub4e0 \ud14c\uc2a4\ud2b8 \ucf54\ub4dc\ub97c AST\ub85c \ubd84\uc11d\ud574\uc11c AI \uae30\ubc18\uc73c\ub85c \ub77c\uc774\ube0c\ub7ec\ub9ac \uad50\uccb4\ud558\ub294 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc774\ud6c4\uc5d0 \ub2e4\ub978 \ud328\ub7ec\ub2e4\uc784\uc744 \uc801\uc6a9\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub85c \uad50\uccb4\ud560 \ub54c \ud68d\uae30\uc801\uc73c\ub85c \ub2e8\ucd95\ud574\uc8fc\uc9c0\ub294 \uc54a\uc9c0\ub9cc \uc0c8\ub85c\uc6b4 \uc811\uadfc\ubc29\uc2dd\uc774\uace0 \uc8fc\ubaa9\ud574\ubcfc\ub9cc\ud55c \uc0ac\ub840\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"156b3589-12b0-4b07-bcf4-0c72c859e299\\" id=\\"156b3589-12b0-4b07-bcf4-0c72c859e299\\">React \ucef4\ud30c\uc77c\ub7ec\uc758 \uc774\ud574</h2><a href=\\"https://tonyalicea.dev/blog/understanding-react-compiler/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tonyalicea.dev/blog/understanding-react-compiler/</a><p data-notion-block-id=\\"fe3c627b-f4f8-405e-8efa-8dceb5350353\\"><b>\uc2ec\uc724\uc12d</b>: React \ucef4\ud30c\uc77c\ub7ec\ub97c \uc774\ud574\ud558\uae30 \uc804\uc5d0 \ud2b8\ub79c\uc2a4\ud30c\uc77c\ub7ec\uc640 \ucef4\ud30c\uc77c\ub7ec\uc758 \uac1c\ub150, React\uc758 \uae30\ubcf8 \uac1c\ub150\uc744 \uc124\uba85\ud558\uace0 React \ucef4\ud30c\uc77c\ub7ec\uc758 \ub3d9\uc791 \ubc29\uc2dd\uc744 \uc124\uba85\ud569\ub2c8\ub2e4. \uac04\ub2e8\ud55c \uac1c\ub150\uacfc \uba54\ubaa8\uc774\uc81c\uc774\uc158\uc744 \uc704\ud55c \ucd94\uc801 \ubc29\uc2dd\uc758 \uae30\ubcf8\ub9cc \uc124\uba85\ud558\uae30 \ub54c\ubb38\uc5d0, \ucef4\ud30c\uc77c\ub7ec\uc758 \ub0b4\ubd80 \ub3d9\uc791\uacfc \uc801\uc6a9\ub41c \uc774\ub860\uc744 \uc790\uc138\ud558\uac8c \ubcf4\ub824\uba74 <a href=\\"https://www.recompiled.dev/tags/compiler/\\">\uac1c\ubc1c\uc790\uc758 \ube14\ub85c\uadf8 \uae00</a>\uc744 \ubcf4\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4(\ud2b9\ud788 <a href=\\"https://ones-to-watch.ethansup.net/news/post/30480561-d12b-484b-9886-1eafeb5b6d35#2c964c01-95ca-4ec2-a409-d151ee87b9ea\\">React \ucef4\ud30c\uc77c\ub7ec\uc758 \ud0c0\uc785 \uc2dc\uc2a4\ud15c</a>\uc744 \ubcf4\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4).</p><h2 data-notion-block-id=\\"71e842c6-392d-4954-bc39-c48745907058\\" id=\\"71e842c6-392d-4954-bc39-c48745907058\\">React\uc758 \ubbf8\ub798?</h2><a href=\\"https://bobaekang.com/blog/component-colocation-composition/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://bobaekang.com/blog/component-colocation-composition/</a><p data-notion-block-id=\\"a4931f24-588b-4ac8-8f5c-dfdaa3c97cee\\"><b>\uc2ec\uc724\uc12d</b>: React\uc758 \ucef4\ud3ec\ub10c\ud2b8, \uac00\uc0c1\ub3d4, \ub77c\uc774\ube0c\ub7ec\ub9ac \uc0dd\ud0dc\uacc4\uc758 \uac1c\ub150\uc740 \uc88b\ub4e0 \uc2eb\ub4e0 \ud504\ub860\ud2b8\uc5d4\ub4dc\uc758 \ubcc0\ud654\ub97c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \ud604\uc7ac React\ub294 UI \ub85c\uc9c1\uc5d0\ub9cc \uad00\uc5ec\ud588\ub358 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0dd\ud0dc\uacc4\uc5d0\uc11c \uc2e0\uacbd \uc37c\ub358 \ubb38\uc81c \uc0c1\ud669(\uc8fc\ub85c UI)\uc744 React \ub0b4\ub85c \uac00\uc838\uc624\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\uc640 \uac19\uc774 \uba54\ud0c0 \ud504\ub808\uc784\uc6cc\ud06c\uc640\uc758 \ud611\ub825\uc73c\ub85c \uc791\uac8c\ub294 \uc778\uc2a4\ud134\uc2a4, \ub113\uac8c\ub294 \uc778\ud504\ub77c\uae4c\uc9c0 \ub2e4\ub8f0 \uc218 \uc788\ub3c4\ub85d \ud55c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. React\uc5d0 \ubc18\uac10\uc744 \uac00\uc9c4 \ub2e4\ub978 \ud504\ub808\uc784\uc6cc\ud06c\uac00 \uac11\uc790\uae30 \ub5a0\uc624\ub974\uac70\ub098, \uc544\ub2c8\uba74 React\uc758 \uc0dd\ud0dc\uacc4 \ub85c\uc9c1\uc744 React \ub85c\uc9c1 \ub0b4\ubd80\ub85c \ub4e4\uc5ec\uc62c \uc218 \uc788\uc744 \uac83\uc778\uc9c0 \uc9c0\ucf1c\ubd10\uc57c \ud560 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \ubc88\uc678\ub85c React Native\uc5d0\uc11c\ub3c4 \uba54\ud0c0 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \ub354\uc6b1 \uad8c\uc7a5\ud558\uace0 \uc788\uc5b4\uc11c, \uba54\ud0c0 \ud504\ub808\uc784\uc6cc\ud06c\uc758 \ubc29\ud5a5\ub3c4 \uc2e0\uacbd\uc368\uc57c \ud560 \uac83 \uac19\ub124\uc694(<a href=\\"https://reactnative.dev/blog/2024/06/25/use-a-framework-to-build-react-native-apps\\">\ud504\ub808\uc784\uc6cc\ud06c\ub97c \uc0ac\uc6a9\ud558\uc5ec React Native \uad6c\ucd95</a>).</p><h3 data-notion-block-id=\\"32fe251e-77ed-451d-89a0-52af06e53078\\">\ubaa8\ub178\ub808\ud3ec\uc5d0\uc11c\uc758 TypeScript</h3><a href=\\"https://colinhacks.com/essays/live-types-typescript-monorepo\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://colinhacks.com/essays/live-types-typescript-monorepo</a><p data-notion-block-id=\\"9a66a3dd-6c70-44a2-9362-4678888f062f\\"><b>\uc2ec\uc724\uc12d</b>: \ubaa8\ub178\ub808\ud3ec \uc2dd\uc73c\ub85c \uc138\ud305\ud558\uba74\uc11c, \ub2e4\ub978 \ud328\ud0a4\uc9c0\ub098 \uc571\uc5d0\uc11c \ud0c0\uc785\uc744 \uac00\uc838\uc624\ub294 \uac83\uc740 \ubcf4\ud1b5 <code>tsconfig.json</code>\uc758 <code>reference</code>\ub97c \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\uc9c0\ub9cc, \uadf8\ub7fc\uc5d0\ub3c4 \uc720\ud615\uc744 \uac00\uc838\uc624\uac70\ub098 \ud0c0\uc785 \uc0dd\uc131, \ub2e4\ub978 \ub3c4\uad6c\uc640 \ud1b5\ud569\uc5d0 \uc5b4\ub824\uc6c0\uc744 \uacaa\uae30\ub3c4 \ud569\ub2c8\ub2e4. \uc774\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 \uc5ec\ub7ec\uac00\uc9c0 \ubc29\uc2dd\uc744 \uc81c\uc548\ud569\ub2c8\ub2e4. \uc8fc\ub85c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ud65c\uc6a9\ud558\ub294 \ubc29\uc2dd\uc774\uc9c0\ub9cc, <code>package.json</code>\uc744 \ud1b5\ud574\uc11c \uc811\uadfc\ud558\ub294 \ubc29\uc2dd\uc774 \ub208\uc5d0 \ub744\ub124\uc694.</p><h2 data-notion-block-id=\\"21264851-e436-41c8-beaa-612f13923cca\\" id=\\"21264851-e436-41c8-beaa-612f13923cca\\">CSS hack\uacfc \uc0c8\ub85c\uc6b4 \uce5c\uad6c\ub4e4</h2><a href=\\"https://whatislove.dev/articles/bem-modifiers-in-pure-css-nesting/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://whatislove.dev/articles/bem-modifiers-in-pure-css-nesting/</a><p data-notion-block-id=\\"3e2036e0-0e83-451d-82c7-522fc97de238\\"></p><a href=\\"https://geoffgraham.me/conditionals-on-custom-properties/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://geoffgraham.me/conditionals-on-custom-properties/</a><a href=\\"https://lea.verou.me/blog/2024/css-conditionals-now\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://lea.verou.me/blog/2024/css-conditionals-now</a><p data-notion-block-id=\\"eb9faf84-24b7-4cd8-afbf-cb66f3c4ca9b\\"></p><a href=\\"https://developer.chrome.com/blog/new-in-web-ui-io-2024?hl=ko\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.chrome.com/blog/new-in-web-ui-io-2024?hl=ko</a><a href=\\"https://www.stefanjudis.com/blog/safari-18-what-web-features-are-usable-across-browsers/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.stefanjudis.com/blog/safari-18-what-web-features-are-usable-across-browsers/</a><p data-notion-block-id=\\"74a085f3-f88f-4ba3-a1ba-70aa78352f96\\">\uccab\ubc88\uc9f8 \uae00\uc740 CSS Nesting \uae30\ub2a5\uc744 \ud1b5\ud574 BEM modifier\ub97c \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc27d\uac8c \ud45c\ud604\ud558\ub294 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \ubb3c\ub860 <code>&#x26;</code>\ub4a4\uc5d0 modifier\uae4c\uc9c0 \ubaa8\ub450 \ubd99\uc778 class\ub97c \ubd99\uc774\ub294 \uac83\uacfc \ud638\ubd88\ud638\uac00 \uac08\ub9b4 \uc218\ub3c4 \uc788\uaca0\ub124\uc694. \uadf8\ub9ac\uace0 2\ubc88\uc9f8 \uae00\uc740 CSS\uc5d0 if \ud568\uc218\uac00 \ub17c\uc758 \ub420 \uc608\uc815\uc774\ub77c\ub294 \uc18c\uc2dd\uc5d0 \ub300\ud55c \uae00\uc774\uace0, 3\ubc88\uc9f8 \uae00\uc740 \ube0c\ub77c\uc6b0\uc800\uae4c\uc9c0 \uc624\uae30 \uc804\uae4c\uc9c0 \uadf8\ub3d9\uc548 \uc870\uac74\ubd80 \uac12\uc744 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud558\uc600\ub294\uc9c0\uc5d0 \ub300\ud574 \uc5ec\ub7ec\uac00\uc9c0 \ubc29\ubc95\uc744 \uc81c\uc2dc\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud568\uc218\ub85c \ub098\uc628 \ub9cc\ud07c \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uac00 \uc544\ub2cc \ube0c\ub77c\uc6b0\uc800\uc758 \ud3f4\ub9ac\ud544\uc774 \uc5b4\ub5bb\uac8c \uc9c4\ud589\ub420\uc9c0\ub3c4 \uad81\uae08\ud574\uc9c0\ub124\uc694. \ub05d 2\uac1c\uc758 \uae00\uc740 CSS \uc704\uc8fc\uc758 \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uc4f8 \uc218 \uc788\ub294 \uc18d\uc131\ub4e4\uc744 \uc18c\uac1c\ud574\uc8fc\ub294 \uae00\ub4e4\uc785\ub2c8\ub2e4. \ub9ce\uc774 \uc720\uba85\ud574\uc9c4 Container Query\uc640 <code>@property</code>, CSS nesting\uc774 \uc788\uc9c0\ub9cc block\uc5d0\uc11c\uc758 \uac00\uc6b4\ub370 \uc815\ub82c\uacfc safe flexbox\uac00 \ub208\uc5d0 \ub744\ub124\uc694.</p><h2 data-notion-block-id=\\"1478c8da-f285-41b3-8a8e-b495fbf5ffd3\\" id=\\"1478c8da-f285-41b3-8a8e-b495fbf5ffd3\\">State of JS 2023</h2><a href=\\"https://2023.stateofjs.com/en-US\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://2023.stateofjs.com/en-US</a><p data-notion-block-id=\\"c3ae592b-cb94-4dd8-8a1f-4cbb06b984e3\\">JS\uc758 \uc2e0\uae30\uc220\uc774 \ubb34\uc5c7\uc774 \uc788\ub294\uc9c0, \uadf8\uc5d0 \ub300\ud55c \ub2e4\ub978 \uac1c\ubc1c\uc790\ub4e4\uc758 \uc0dd\uac01\uc740 \uc5b4\ub5a8\uae4c\uc5d0 \ub300\ud574 \ubcfc \uc218 \uc788\ub294 \uc124\ubb38\uacb0\uacfc\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"bbf8ed02-826b-456f-9cec-ac45e727fab7\\" id=\\"bbf8ed02-826b-456f-9cec-ac45e727fab7\\">Queue \uc124\uba85 \uc2dc\uac01\ud654</h2><a href=\\"https://encore.dev/blog/queueing\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://encore.dev/blog/queueing</a><p data-notion-block-id=\\"d0c55d2f-57ec-4010-a4f3-848a491002d3\\">\uc7ac\ubc0c\ub294 \uc560\ub2c8\uba54\uc774\uc158\uacfc \ud568\uaed8 Queue\uc758 \uc885\ub958\ub97c \uc774\ud574\ud560 \uc218 \uc788\ub3c4\ub85d \ub3d5\uc2b5\ub2c8\ub2e4. SSR\uc774 \uc911\uc694\uc2dc\ub418\ub294 \uc9c0\uae08 \uc911\uc694\ud55c \uac1c\ub150\uc774\ub77c\uace0 \uc0dd\uac01\ub418\ub124\uc694.</p><h2 data-notion-block-id=\\"509c92d8-319f-41ed-832e-4350eb511907\\" id=\\"509c92d8-319f-41ed-832e-4350eb511907\\">React \ub3d9\uc791 \ubc29\uc2dd \uc2dc\uac01\ud654</h2><a href=\\"https://jser.dev/2024-05-11-introducing-rie/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jser.dev/2024-05-11-introducing-rie/</a><p data-notion-block-id=\\"c1fa7e6f-68c1-45b2-bd94-6c1941074eed\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/022fc2c2-88d3-4c20-9075-defdea8ae65c#2d01841e-9fc5-4807-99d5-d8d2a73be23e\\">React \ub0b4\ubd80 \ub525 \ub2e4\uc774\ube0c</a> \uc2dc\ub9ac\uc988\uc758 \uc800\uc790\uac00 \uc2dc\uac01\ud654 \ub2e4\uc774\uc5b4\uadf8\ub7a8 \uc0ac\uc774\ud2b8\ub97c \ub9cc\ub4e4\uc5c8\ub124\uc694. \ub354 \uc27d\uac8c \ub3d9\uc791 \ubc29\uc2dd\uc744 \uc774\ud574\ud560 \uc218 \uc788\uc744 \uac83 \uac19\ub124\uc694.</p><h2 data-notion-block-id=\\"6e09df7f-5435-4f05-9bde-f8c17d5c074c\\" id=\\"6e09df7f-5435-4f05-9bde-f8c17d5c074c\\">INP\uac00 \ub9d0\ud558\uace0\uc790 \ud558\ub294 \uac83</h2><a href=\\"https://vercel.com/blog/demystifying-inp-new-tools-and-actionable-insights\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vercel.com/blog/demystifying-inp-new-tools-and-actionable-insights</a><p data-notion-block-id=\\"74740794-6d79-4e10-9021-4b93efc93820\\">\uba54\uc778\uc2a4\ub808\ub4dc\ub97c block\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc774\ubca4\ud2b8 \uc2e4\ud589 \uc2dc\uc5d0 \uc0dd\uae30\ub294 \uae34 \uc791\uc5c5\uc744 \ucabc\uac1c\ub294 \uac83\uc744 \ud574\ub2ec\ub77c\ub294 INP\uc5d0 \ub300\ud55c \ubd84\uc11d\uc785\ub2c8\ub2e4. \uc774 \uacfc\uc815\uc5d0\uc11c <code>await-interaction-response</code>\ub97c \uc0ac\uc6a9\ud558\uac70\ub098 <code>useTransition</code>\uc744 \uc4f0\uba74 \ud574\uacb0\ud560 \uc218 \uc788\ub2e4\ub294 \ud574\uacb0\ucc45\uacfc \uac19\uc774\uc694.</p><h2 data-notion-block-id=\\"9563263e-534e-4214-b644-51b0054a213e\\" id=\\"9563263e-534e-4214-b644-51b0054a213e\\">\uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\uc758 \ubb34\uc791\uc704\uc131</h2><a href=\\"https://www.bennadel.com/blog/4669-exploring-randomness-in-javascript.htm\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.bennadel.com/blog/4669-exploring-randomness-in-javascript.htm</a><p data-notion-block-id=\\"9a34a6b7-f9fe-48b5-a344-3129c5e90b51\\"><code>Math.random</code>\uc740 <code>crypto.getRandomValues</code>\ubcf4\ub2e4 \ubd88\uc548\uc804\ud55c \ub09c\uc218\ub97c \uc0ac\uc6a9\ud55c\ub2e4\uace0 \ud558\uc9c0\ub9cc, \uacf5\uaca9\uc790 \uc785\uc7a5\uc774 \uc544\ub2cc \uc0ac\uc6a9\uc790 \uc785\uc7a5\uc5d0\uc11c \ub09c\uc218 \uc0dd\uc131\uc740 \ub290\ub08c\uc77c \uac00\ub2a5\uc131\uc774 \ub192\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc800\uc790\ub294 \ub450\uac00\uc9c0 \ubc29\uc2dd\uc744 \ud1b5\ud574 \ub09c\uc218\ub97c \uc0dd\uc131\ud558\uace0 \uc5f0\uc18d\uc801\uc73c\ub85c \uc0dd\uc131\ub420 \ud655\ub960\uc744 \uccb4\ud06c\ud558\uace0, \ub290\ub08c\uc801\uc778 \uba74\uc5d0\uc11c\ub294 \ud06c\uac8c \ub2e4\ub974\uc9c0 \uc54a\ub2e4\ub294 \uc0dd\uac01\uc744 \ub9d0\ud569\ub2c8\ub2e4.</p>"}')}}]);